contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint256 seedAmount) public payable {
        require(seedAmount > 0);

        c.seedMarket(seedAmount); if (__ESBMC_reverted()) return;
        bool initAfterSeed = c.initialized(); if (__ESBMC_reverted()) return;
        uint256 marketAfterSeed = c.marketDrugs(); if (__ESBMC_reverted()) return;

        c.getFreeKilo(); if (__ESBMC_reverted()) return;
        bool initAfterFree = c.initialized(); if (__ESBMC_reverted()) return;
        uint256 marketAfterFree = c.marketDrugs(); if (__ESBMC_reverted()) return;

        assert(
            initAfterSeed == true &&
            initAfterFree == true &&
            marketAfterSeed == seedAmount &&
            marketAfterFree == seedAmount
        );
    }
}

