pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherCartel c;

    function setUp() public {
        c = new EtherCartel();
    }

    function _run(uint256 seedAmount) internal {
        vm.assume(seedAmount > 0);
        try c.seedMarket(seedAmount) {} catch { return; }
        bool initAfterSeed;
        try c.initialized() returns (bool __r) { initAfterSeed = __r; } catch { return; }
        uint256 marketAfterSeed;
        try c.marketDrugs() returns (uint256 __r) { marketAfterSeed = __r; } catch { return; }
        try c.getFreeKilo() {} catch { return; }
        bool initAfterFree;
        try c.initialized() returns (bool __r) { initAfterFree = __r; } catch { return; }
        uint256 marketAfterFree;
        try c.marketDrugs() returns (uint256 __r) { marketAfterFree = __r; } catch { return; }
        assertTrue(initAfterSeed == true &&
            initAfterFree == true &&
            marketAfterSeed == seedAmount &&
            marketAfterFree == seedAmount);
    }

    function testFuzz_run(uint256 seedAmount) public {
        _run(seedAmount);
    }

    receive() external payable {}
}
